class Solution {
public:
    vector<string> findRestaurant(vector<string>& list1, vector<string>& list2) {
        unordered_map<string, int> idxMap;
        for (int i = 0; i < (int)list1.size(); i++) idxMap[list1[i]] = i;
        int minSum = INT_MAX;
        vector<string> res;
        for (int j = 0; j < (int)list2.size(); j++) {
            auto it = idxMap.find(list2[j]);
            if (it != idxMap.end()) {
                int total = j + it->second;
                if (total < minSum) {
                    minSum = total;
                    res = {list2[j]};
                } else if (total == minSum) {
                    res.push_back(list2[j]);
                }
            }
        }
        return res;
    }
};

class Solution {
    public String[] findRestaurant(String[] list1, String[] list2) {
        Map<String, Integer> idxMap = new HashMap<>();
        for (int i = 0; i < list1.length; i++) idxMap.put(list1[i], i);
        int minSum = Integer.MAX_VALUE;
        List<String> res = new ArrayList<>();
        for (int j = 0; j < list2.length; j++) {
            if (idxMap.containsKey(list2[j])) {
                int total = j + idxMap.get(list2[j]);
                if (total < minSum) {
                    minSum = total;
                    res.clear();
                    res.add(list2[j]);
                } else if (total == minSum) {
                    res.add(list2[j]);
                }
            }
        }
        return res.toArray(new String[0]);
    }
}

